// The host calls this before it installs its game resource loaders.
const nativeFetch=globalThis.fetch.bind(globalThis);
const prefix='/codex-rts-play/';
const memoryLimit=100*1024*1024;
const decodedPath=loc=>decodeURIComponent(loc.pathname);
const sizeLabel=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KiB':(n/1048576).toFixed(2)+' MiB';
const fileName=path=>path.slice(path.lastIndexOf('/')+1);
function asHex(bytes){
  return Array.from(new Uint8Array(bytes), part=>part.toString(16).padStart(2,'0')).join('');
}

export function installStartupTransfers(configuration){
  const {packIndex, packs, assetBuildId, scope, includeAudio}=configuration;
  const planned=new Map(Object.entries(packIndex));
  const transferRoot=new URL('../packs/',location.href);
  let epoch=0;
  let mode='menu';
  let observeFrom=0;
  let files=new Map();
  let cachedBytes=0;
  let opened=false;
  let usedCard=null;
  let details=null;
  let refreshTimer=null;
  let bootCard=null;
  let planNames=[];
  const packCache=new Map();

  function file(path,started){
    let record=files.get(path);
    if(!record){
      record={name:fileName(path),state:'Downloading',bytes:0,total:null,first:started,attempts:0,packed:false,progress:0};
      files.set(path,record);
    }
    return record;
  }
  function watchURL(url){
    return url.origin===location.origin &&
      (url.pathname.startsWith(prefix)||url.pathname.startsWith(transferRoot.pathname)||url.pathname.startsWith(scope));
  }
  function capture(kind,time){
    epoch++;
    mode=kind;
    observeFrom=time;
    files=new Map();
    opened=false;
    const values=name=>document.querySelector('[aria-label="'+name+'"]')?.value;
    const standard=kind==='game'&&values('Setup Seed')==='terran-ground-mission-vertical-slice:ordinary-setup-v1'&&
      values('Difficulty')==='scenario-default'&&values('Player Spawn')==='scenario-default'&&
      values('Player Color')==='approved-cobalt-player'&&values('Enemy Strategy')==='balanced-adaptation';
    const selected=values('Asset Quality');
    const quality=selected==='quality-runtime-2x'?2:selected==='performance-1x'?1:0;
    planNames=standard&&quality?Object.keys(packs).filter(name=>packs[name].qualities.includes(quality)):[];
    releaseUnusedPacks();
  }
  function releaseUnusedPacks(){
    for(const [name,pack] of packCache){
      if(pack.consumers>0)continue;
      if(!pack.bytes)pack.controller.abort();
      else cachedBytes-=pack.bytes.byteLength;
      packCache.delete(name);
    }
  }
  function trim(){
    if(cachedBytes<=memoryLimit)return;
    for(const [name,pack] of packCache){
      if(pack.consumers!==0||!pack.bytes)continue;
      cachedBytes-=pack.bytes.byteLength;
      packCache.delete(name);
      if(cachedBytes<=memoryLimit)return;
    }
  }
  function detailsUI(card){
    if(usedCard===card&&details?.isConnected)return;
    usedCard=card;
    details=document.createElement('details');
    details.className='r3-loading-details';
    details.open=opened;
    const summary=document.createElement('summary');
    summary.textContent='Loading details';
    const count=document.createElement('p');
    count.setAttribute('data-loading-count','');
    const bytes=document.createElement('p');
    bytes.setAttribute('data-loading-bytes','');
    const rows=document.createElement('ol');
    rows.className='r3-loading-files';
    rows.setAttribute('aria-label','Current file transfers');
    const loose=document.createElement('p');
    loose.setAttribute('data-loading-loose','');
    details.append(summary,count,bytes,loose,rows);
    details.addEventListener('toggle',()=>{if(details?.isConnected)opened=details.open;});
    card.append(details);
  }
  function mount(){
    if(mode==='inactive')return;
    const menu=document.querySelector('.game-menu__start');
    const layer=document.querySelector('.scene-loading-layer .scene-loading-card');
    if(mode==='menu'&&menu){
      bootCard?.remove();
      bootCard=null;
      mode='inactive';
      releaseUnusedPacks();
      return;
    }
    if(mode==='game'&&!layer&&menu&&details?.isConnected===false){
      mode='inactive';
      releaseUnusedPacks();
      return;
    }
    if(mode==='game'&&!layer&&document.querySelector('[data-published-visual-ready="true"]')){
      mode='inactive';
      releaseUnusedPacks();
      return;
    }
    let card=layer;
    if(!card&&mode==='menu'){
      const root=document.getElementById('root');
      if(root?.textContent?.trim()!=='Loading game…'){
        bootCard?.remove();
        bootCard=null;
        return;
      }
      bootCard??=document.createElement('aside');
      bootCard.className='r3-menu-loading';
      if(!bootCard.isConnected)document.body.append(bootCard);
      card=bootCard;
    }
    if(!card)return;
    detailsUI(card);
    const list=[...files.values()];
    const complete=list.filter(row=>row.state==='Complete');
    const downloaded=list.reduce((sum,row)=>sum+row.bytes,0);
    const known=list.reduce((sum,row)=>sum+(row.total??row.bytes),0);
    const receiving=list.filter(row=>row.state==='Downloading'||row.state==='Checking').reduce((sum,row)=>sum+row.progress,0);
    const count=details.querySelector('[data-loading-count]');
    const bytes=details.querySelector('[data-loading-bytes]');
    const planned=planNames.map(name=>({expect:packs[name], seen:files.get(decodedPath(new URL(name,transferRoot)))}));
    const remaining=list.filter(row=>!row.packed);
    const looseComplete=remaining.filter(row=>row.state==='Complete').length;
    if(planned.length){
      const finished=planned.filter(({seen})=>seen?.state==='Complete').length;
      const downloadedPacks=planned.reduce((sum,{seen})=>sum+(seen?.bytes??0),0);
      const payloadBytes=planned.reduce((sum,{expect})=>sum+expect.bytes,0);
      count.dataset.complete=String(finished);
      count.dataset.total=String(planned.length);
      bytes.dataset.downloaded=String(downloadedPacks);
      bytes.dataset.total=String(payloadBytes);
      count.textContent=finished+' / '+planned.length+' planned startup packages loaded';
      bytes.textContent=sizeLabel(downloadedPacks)+' downloaded / '+sizeLabel(payloadBytes)+' planned package payload'
        +(receiving>0?' · '+sizeLabel(receiving)+' currently receiving':'');
      const loose=details.querySelector('[data-loading-loose]');
      loose.textContent=looseComplete+' / '+remaining.length+' individual files discovered · final total pending';
    }else{
      count.textContent=complete.length+' / '+list.length+' files discovered · final total pending';
      bytes.textContent=sizeLabel(downloaded)+' downloaded · '+sizeLabel(known)+' known so far'
        +(receiving>0?' · '+sizeLabel(receiving)+' currently receiving':'');
    }
    if(!opened)return;
    const rows=list.filter(row=>row.state!=='Complete').slice(-20);
    if(rows.length<20)rows.unshift(...complete.slice(-(20-rows.length)));
    const tail=details.querySelector('.r3-loading-files');
    tail.replaceChildren(...rows.map(record=>{
      const li=document.createElement('li');
      const label=document.createElement('span');
      label.textContent=record.name;
      label.title=record.name;
      const state=document.createElement('span');
      const completed=record.state==='Complete'||record.state==='Cached';
      state.textContent=record.state+(record.total===null?'':' · '+sizeLabel(completed?record.bytes:record.progress)+' / '+sizeLabel(record.total))
        +(record.attempts>1?' · attempt '+record.attempts:'');
      li.append(label,state);
      return li;
    }));
  }

  function requestMeta(input,init){
    if(input instanceof Request)return null;
    if(typeof input!=='string'&&!(input instanceof URL))return null;
    if(init?.method&&init.method.toUpperCase()!=='GET')return null;
    const url=new URL(input,location.href);
    if(!watchURL(url))return null;
    const path=decodedPath(url);
    const keys=[...url.searchParams.keys()];
    const eligible=mode==='game'&&planned.has(path)&&!new Headers(init?.headers).has('range')&&
      (!keys.length||(keys.length===1&&keys[0]==='rts-build'&&url.searchParams.get('rts-build')===assetBuildId));
    return {path,eligible,url};
  }
  function nextPack(name,context,generation){
    const previous=packCache.get(name);
    if(previous){
      packCache.delete(name);
      packCache.set(name,previous);
      return previous;
    }
    const expected=packs[name];
    const controller=new AbortController();
    const entry={controller,consumers:0,bytes:null,promise:null};
    packCache.set(name,entry);
    const url=new URL(name,transferRoot);
    const row=file(decodedPath(url),performance.now());
    row.packed=true;
    row.state='Downloading';
    row.attempts++;
    row.total=null;
    row.progress=0;
    entry.promise=(async()=>{
      try{
        const response=await nativeFetch(url,{signal:controller.signal,cache:row.attempts===1?'force-cache':'reload'});
        if(!response.ok)throw Error('HTTP '+response.status+': '+url.pathname);
        if(!response.body)throw Error('Startup archive stream missing');
        const length=response.headers.get('content-length');
        const lengthNumber=length===null?null:Number(length);
        if(Number.isSafeInteger(lengthNumber)&&lengthNumber>=0)row.total=lengthNumber;
        const identityEncoding=!response.headers.get('content-encoding');
        const output=new Uint8Array(expected.bytes);
        const reader=response.body.getReader();
        let offset=0;
        try{
          for(;;){
            const {value,done}=await reader.read();
            if(done)break;
            if(offset+value.length>output.byteLength)throw Error('Startup archive exceeds its verified length');
            output.set(value,offset);
            offset+=value.length;
            // ResourceTiming supplies compressed byte counts when HTTP uses encoding.
            if(identityEncoding)row.progress=offset;
          }
        }catch(error){
          void reader.cancel().catch(()=>{});
          throw error;
        }finally{
          reader.releaseLock();
        }
        row.state='Checking';
        if(offset!==expected.bytes||asHex(await crypto.subtle.digest('SHA-256',output))!==expected.sha256){
          throw Error('Startup archive integrity mismatch: '+name);
        }
        if(controller.signal.aborted)throw controller.signal.reason??new DOMException('Cancelled','AbortError');
        entry.bytes=output;
        cachedBytes+=output.byteLength;
        if(files===context&&epoch===generation)row.state='Complete';
        return output;
      }catch(error){
        row.state=controller.signal.aborted?'Cancelled':'Failed';
        if(packCache.get(name)===entry)packCache.delete(name);
        throw error;
      }
    })();
    return entry;
  }
  async function withPack(name,signal){
    if(signal?.aborted)throw signal.reason??new DOMException('Cancelled','AbortError');
    const pack=nextPack(name,files,epoch);
    pack.consumers++;
    let abort;
    try{
      if(!signal)return await pack.promise;
      return await Promise.race([pack.promise,new Promise((_,reject)=>{
        abort=()=>reject(signal.reason??new DOMException('Cancelled','AbortError'));
        signal.addEventListener('abort',abort,{once:true});
        if(signal.aborted)abort();
      })]);
    }finally{
      if(abort)signal.removeEventListener('abort',abort);
      pack.consumers--;
      if(!pack.consumers&&!pack.bytes&&signal?.aborted)pack.controller.abort();
      trim();
    }
  }

  async function fetchStartup(input,init){
    let meta;
    try{meta=requestMeta(input,init);}
    catch{return nativeFetch(input,init);}
    if(!meta||mode==='inactive')return nativeFetch(input,init);
    const entry=planned.get(meta.path);
    if(meta.eligible&&entry&&(includeAudio||packs[entry[0]].media==='image')){
      const [packageName,offset,length,type]=entry;
      const blob=await withPack(packageName,init?.signal);
      return new Response(blob.subarray(offset,offset+length),{
        status:200,headers:{'Content-Type':type,'Content-Length':String(length)}
      });
    }
    const row=file(meta.path,performance.now());
    row.attempts++;
    row.state='Downloading';
    try{
      const response=await nativeFetch(input,init);
      if(!response.ok){
        row.state='Failed';
        return response;
      }
      const header=response.headers.get('content-length');
      if(header!==null&&/^\d+$/.test(header))row.total=Number(header);
      return response;
    }catch(error){
      row.state=init?.signal?.aborted?'Cancelled':'Failed';
      throw error;
    }
  }

  performance.setResourceTimingBufferSize(7500);
  try{
    new PerformanceObserver(list=>{
      if(mode==='inactive')return;
      for(const entry of list.getEntries()){
        if(entry.startTime<observeFrom||!/https?:/.test(entry.name.slice(0,10)))continue;
        const url=new URL(entry.name);
        if(!watchURL(url))continue;
        const row=file(decodedPath(url),entry.startTime);
        if(entry.encodedBodySize>0){
          if(entry.transferSize>0)row.bytes=Math.max(row.bytes,entry.encodedBodySize);
          row.total??=entry.encodedBodySize;
        }
        if(entry.responseStatus>=400){
          row.state='Failed';
        }else if(row.state!=='Checking'&&(!row.packed||row.state==='Complete')){
          row.state='Complete';
        }
      }
    }).observe({type:'resource',buffered:true});
  }catch{}
  document.addEventListener('click',event=>{
    const button=event.target instanceof Element?event.target.closest('button'):null;
    if(['Start Game','Retry'].includes(button?.textContent?.trim())&&
      (button?.classList.contains('game-menu__start')||button?.closest('.scene-loading-layer'))){
      details?.remove();
      details=null;
      bootCard?.remove();
      bootCard=null;
      capture('game',performance.now());
    }
  },{capture:true});
  refreshTimer=setInterval(mount,200);
  window.addEventListener('pagehide',()=>{
    if(refreshTimer)clearInterval(refreshTimer);
    mode='inactive';
    releaseUnusedPacks();
  },{once:true});
  globalThis.fetch=fetchStartup;
}

